struct Countdown {
    int n;
    struct It {
        int v;
        int operator*() const { return v; }
        bool operator!=(const It &o) const { return v != o.v; }
        It &operator++() { --v; return *this; }
    };
    It begin() const { return {n}; }
    It end() const { return {0}; }
};
for (int v : Countdown{3}) use(v);   // 3, 2, 1 - produced on demand

