std::generator<int> iota(int n) {       // C++23; C++20 needs a promise type
    for (int i = 0; i < n; ++i)
        co_yield i;                      // suspend and hand out one value
}

for (int v : iota(5)) use(v);            // 0 1 2 3 4, lazily
